-- ================================================================
-- Supabase Schema Migration for HackerRank Peer Analytics Tracker
-- ================================================================

-- 1. Create the tracked_profiles table
CREATE TABLE IF NOT EXISTS public.tracked_profiles (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    username TEXT UNIQUE NOT NULL,
    name TEXT,
    personal_first_name TEXT,
    personal_last_name TEXT,
    avatar TEXT,
    country TEXT DEFAULT 'India',
    school TEXT,
    company TEXT,
    job_title TEXT,
    github_url TEXT,
    linkedin_url TEXT,
    website TEXT,
    created_at TIMESTAMPTZ DEFAULT now(),
    updated_at TIMESTAMPTZ DEFAULT now(),
    level INT DEFAULT 1,
    
    -- HackerRank Derived Metrics
    total_solved INT DEFAULT 0,
    total_stars INT DEFAULT 0,
    total_points NUMERIC DEFAULT 0,
    best_rank TEXT,
    badges JSONB DEFAULT '[]'::jsonb,
    scores JSONB DEFAULT '[]'::jsonb,
    active_tracks JSONB DEFAULT '[]'::jsonb,
    submissions JSONB DEFAULT '[]'::jsonb,
    heatmap JSONB DEFAULT '{}'::jsonb,
    
    -- Sync Metadata
    last_synced_at TIMESTAMPTZ,
    last_successful_sync_at TIMESTAMPTZ,
    last_sync_status TEXT DEFAULT 'success',
    last_sync_error TEXT,
    
    -- Admin Metadata
    custom_meta JSONB DEFAULT '{"department": "Engineering", "batch": "Core Group", "status": "Active", "notes": ""}'::jsonb
);

-- 2. Indexes for high-performance sorting and query speed
CREATE INDEX IF NOT EXISTS idx_tracked_profiles_username ON public.tracked_profiles (username);
CREATE INDEX IF NOT EXISTS idx_tracked_profiles_total_solved ON public.tracked_profiles (total_solved DESC);
CREATE INDEX IF NOT EXISTS idx_tracked_profiles_total_stars ON public.tracked_profiles (total_stars DESC);
CREATE INDEX IF NOT EXISTS idx_tracked_profiles_total_points ON public.tracked_profiles (total_points DESC);

-- 3. Enable Row Level Security (RLS)
ALTER TABLE public.tracked_profiles ENABLE ROW LEVEL SECURITY;

-- 4. Public Read Policy (Anyone with the link can view the peer analytics)
DROP POLICY IF EXISTS "Public Read Access" ON public.tracked_profiles;
CREATE POLICY "Public Read Access" 
ON public.tracked_profiles 
FOR SELECT 
USING (true);

-- 5. Service Role / Admin Policy (Full CRUD for backend API / Edge Functions)
DROP POLICY IF EXISTS "Service Role Access" ON public.tracked_profiles;
CREATE POLICY "Service Role Access" 
ON public.tracked_profiles 
FOR ALL 
TO service_role 
USING (true) 
WITH CHECK (true);

